from pathlib import Path

Path('tests/test_do_plan_72h.py').write_text('''from datetime import datetime, timedelta, timezone\nimport importlib.util\nfrom pathlib import Path\n\nROOT = Path(__file__).parents[1]\nMODULE_PATH = ROOT / "custom_components/dummy_os_data/do_plan_72h.py"\nSPEC = importlib.util.spec_from_file_location("do_plan_72h", MODULE_PATH)\nassert SPEC is not None and SPEC.loader is not None\nMOD = importlib.util.module_from_spec(SPEC)\nSPEC.loader.exec_module(MOD)\nbuild_do_plan_72h = MOD.build_do_plan_72h\n\ndef make_rows():\n    start=datetime(2026,9,10,tzinfo=timezone.utc)\n    return [{"index":i,"start":(start+timedelta(hours=i)).isoformat(),"end":(start+timedelta(hours=i+1)).isoformat(),"home_kwh":0.5,"solar_kwh":0.0,"import_price":0.2,"export_price":0.1,"fully_valid":True} for i in range(72)]\n\ndef base_inputs():\n    rows=make_rows(); sig="abc"\n    inp={"status":"ready","fully_valid_hours":72,"rows_signature":sig,"rows":rows}\n    reserve={"status":"ready","valid":True,"input_rows_signature":sig,"soc_percent":80.0,"reserve_soc_target_percent":12.0}\n    preview={"status":"ready","valid":True,"input_rows_signature":sig,"safety_charge_hours":[],"self_use_trade_profitable":False,"export_trade_profitable":False}\n    return inp,reserve,preview\n\ndef test_exact_72_and_observer_rights():\n    i,r,p=base_inputs(); out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p)\n    assert out["hour_count"]==72 and len(out["hours"])==72\n    assert out["shadow_only"] is True and out["active_use_permitted"] is False and out["physical_execution_authority"] is False\n    assert out["plan_store_write"] is False and out["scheduler_invoked"] is False and out["safety_chain_invoked"] is False and out["service_calls_performed"] is False\n\ndef test_signature_mismatch_blocks():\n    i,r,p=base_inputs(); p["input_rows_signature"]="wrong"; out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); assert out["status"]=="blocked" and "input_signature_mismatch" in out["blockers"]\n\ndef test_missing_value_blocks_not_zero():\n    i,r,p=base_inputs(); i["rows"][3]["home_kwh"]=None; out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); assert out["status"]=="blocked" and out["hour_count"]==0\n\ndef test_real_zero_is_valid():\n    i,r,p=base_inputs(); i["rows"][0]["home_kwh"]=0.0; i["rows"][0]["solar_kwh"]=0.0; out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); assert out["status"] in {"ready","infeasible"} and out["missing_as_zero_used"] is False\n\ndef test_solar_first_and_shared_charge_limit():\n    i,r,p=base_inputs(); i["rows"][0]["home_kwh"]=0.5; i["rows"][0]["solar_kwh"]=4.0; p["safety_charge_hours"]=[{"start":i["rows"][0]["start"],"candidate_battery_energy_kwh":2.0}]; out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); h=out["hours"][0]; assert h["solar_to_home_kwh"]==0.5; assert h["grid_to_battery_kwh"] <= 3.2\n\ndef test_trade_two_pass_reports_displacement():\n    i,r,p=base_inputs(); i["rows"][1]["solar_kwh"]=5.0; p.update({"self_use_trade_profitable":True,"best_self_use_margin":0.2,"best_self_use_charge_time":i["rows"][0]["start"],"best_self_use_discharge_time":i["rows"][2]["start"]}); out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); assert out["baseline"] is not None and out["candidate"] is not None and out["solar_displacement_kwh"] >= 0\n\ndef test_full_battery_never_overfills():\n    i,r,p=base_inputs(); r["soc_percent"]=100.0; i["rows"][0]["solar_kwh"]=4.0; out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); assert max(h["end_soc_percent"] for h in out["hours"]) <= 100.0\n\ndef test_export_trade_uses_explicit_candidate():\n    i,r,p=base_inputs(); p.update({"export_trade_profitable":True,"best_export_margin":0.3,"best_export_charge_time":i["rows"][0]["start"],"best_export_discharge_time":i["rows"][1]["start"]}); out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); assert out["trade_candidate"]["kind"]=="export"\n\ndef test_upstream_not_ready_blocks():\n    i,r,p=base_inputs(); i["status"]="runtime_blocked"; out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); assert out["status"]=="blocked"\n''')
